function validate([darts, r]) {
  if (!Array.isArray(darts) || darts.length < 1 || darts.length > 100) return 'darts needs 1 to 100 positions.';
  const seen = new Set();
  for (const p of darts) {
    if (!Array.isArray(p) || p.length !== 2 || !p.every(Number.isInteger)) return 'Each dart is a pair [x, y] of integers.';
    if (p.some(v => v < -10000 || v > 10000)) return 'Each coordinate is between -10000 and 10000.';
    const key = p[0] + ',' + p[1];
    if (seen.has(key)) return 'All darts must be at different positions.';
    seen.add(key);
  }
  if (!Number.isInteger(r) || r < 1 || r > 5000) return 'r is an integer between 1 and 5000.';
  return null;
}

