function numPoints(darts, r) {
  const n = darts.length;
  const eps = 1e-7;
  let best = 1;

  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const [x1, y1] = darts[i];
      const [x2, y2] = darts[j];
      const dx = x2 - x1;
      const dy = y2 - y1;
      const distSq = dx * dx + dy * dy;
      if (distSq > 4 * r * r) {
        continue;
      }
      const dist = Math.sqrt(distSq);
      const h = Math.sqrt(r * r - distSq / 4);
      const midX = (x1 + x2) / 2;
      const midY = (y1 + y2) / 2;
      for (const side of [1, -1]) {
        const cx = midX - side * h * dy / dist;
        const cy = midY + side * h * dx / dist;
        let count = 0;
        for (const [x, y] of darts) {
          if (Math.hypot(x - cx, y - cy) <= r + eps) {
            count++;
          }
        }
        best = Math.max(best, count);
      }
    }
  }
  return best;
}

