function numPoints(darts, r) {
  // Candidate centers: every dart itself, and every point at distance exactly r from two darts,
  // found with angles instead of the perpendicular-offset formula.
  const centers = darts.map(([x, y]) => [x, y]);
  for (const [ax, ay] of darts)
    for (const [bx, by] of darts) {
      if (ax === bx && ay === by) continue;
      const d = Math.sqrt((bx - ax) ** 2 + (by - ay) ** 2);
      if (d > 2 * r) continue;
      const theta = Math.atan2(by - ay, bx - ax);
      const phi = Math.acos(Math.min(1, d / (2 * r)));
      centers.push([ax + r * Math.cos(theta + phi), ay + r * Math.sin(theta + phi)]);
    }
  let answer = 0;
  for (const [cx, cy] of centers) {
    const covered = darts.filter(([x, y]) => (x - cx) ** 2 + (y - cy) ** 2 <= (r + 1e-7) ** 2).length;
    answer = Math.max(answer, covered);
  }
  return answer;
}

