function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  // Rejects inputs where a dart lies within a hair of some candidate rim without being on it,
  // so any reasonable floating-point tolerance gives the same answer.
  const clear = (darts, r) => {
    for (let i = 0; i < darts.length; i++)
      for (let j = i + 1; j < darts.length; j++) {
        const [x1, y1] = darts[i], [x2, y2] = darts[j];
        const dx = x2 - x1, dy = y2 - y1, dsq = dx * dx + dy * dy;
        if (dsq > 4 * r * r) continue;
        const d = Math.sqrt(dsq), h = Math.sqrt(r * r - dsq / 4);
        for (const s of [1, -1]) {
          const cx = (x1 + x2) / 2 - s * h * dy / d, cy = (y1 + y2) / 2 + s * h * dx / d;
          for (const [x, y] of darts) {
            const gap = Math.abs(Math.hypot(x - cx, y - cy) - r);
            if (gap > 1e-11 && gap < 2e-5) return false;
          }
        }
      }
    return true;
  };
  for (;;) {
    let n, r, span, clusters;
    if (size === 'large') {
      n = int(90, 100);
      r = rand() < 0.3 ? int(1, 50) : int(50, 5000);
      span = Math.min(10000, Math.max(8, Math.floor(r * (0.6 + rand() * 4))));
      clusters = int(0, 4);
    } else {
      n = int(1, 8);
      r = int(1, 4);
      span = int(2, 6);
      clusters = int(0, 2);
    }
    const ox = int(-(10000 - span), 10000 - span), oy = int(-(10000 - span), 10000 - span);
    const centers = Array.from({ length: clusters }, () => [int(-span, span), int(-span, span)]);
    const seen = new Set();
    const darts = [];
    let tries = 0;
    while (darts.length < n && tries++ < 100000) {
      let x, y;
      if (centers.length && rand() < 0.7) {
        const [cx, cy] = centers[int(0, centers.length - 1)];
        const w = Math.max(1, Math.floor(r * 1.2));
        x = Math.max(-span, Math.min(span, cx + int(-w, w)));
        y = Math.max(-span, Math.min(span, cy + int(-w, w)));
      } else {
        x = int(-span, span);
        y = int(-span, span);
      }
      const key = (x + ox) + ',' + (y + oy);
      if (seen.has(key)) continue;
      seen.add(key);
      darts.push([x + ox, y + oy]);
    }
    if (darts.length >= 1 && clear(darts, r)) return [darts, r];
  }
}
